const cnt=(n,suf='')=>`<b data-count="${n}" data-suf="${suf}">${n}${suf}</b>`;
const chk=on=>`<span class="cb ${on?'on':''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span>`;
const tbtn=(k,i,on,act='tt')=>`<button class="task ${on?'on':''}" data-act="${act}" data-k="${esc(k)}" data-i="${i}"><span class="bx"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span>${TL[i]}</button>`;
function toast(m,t){const e=document.createElement('div');e.className='toast '+(t||'');e.textContent=m;$('#toasts').appendChild(e);setTimeout(()=>{e.style.transition='.4s';e.style.opacity=0;e.style.transform='translateY(-12px)';setTimeout(()=>e.remove(),420)},2800)}
function modal(html,wide){closeModal();const m=document.createElement('div');m.className='mo';m.innerHTML=`<div class="md ${wide?'w':''}">${html}</div>`;m.addEventListener('mousedown',e=>{if(e.target===m)closeModal()});$('#mroot').appendChild(m);const f=$('input.field,textarea.field',m);if(f&&matchMedia('(pointer:fine)').matches)f.focus()}
const closeModal=()=>{$('#mroot').innerHTML=''};
addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeSplash()}});

/* ============ pages ============ */
const QUOTES=['Small steps, taken daily, move mountains.','Silence the noise. Do the work.','You do not rise to your goals — you fall to your habits.','Discipline is a form of self-respect.','One focused hour beats a distracted day.','Be the person your future self thanks.','Slow is smooth, smooth is fast.','Today’s effort is tomorrow’s ease.'];
const greet=()=>{const h=new Date().getHours();return h<5?'Still up':h<12?'Good morning':h<17?'Good afternoon':h<21?'Good evening':'Good night'};
function missionCard(id){const c=CH[id],sj=SUBJ[c.s],st=gc(id),n=chN(id);return`<article class="card mission tilt rise" data-ch="${id}" data-pr="${prOf(id)}" style="--c:${sj.c};--pc:${prOf(id)?PRI[prOf(id)][1]:'transparent'};${ri()}">${GLT()}<div class="row sp"><div><div class="sub">${esc(sj.n)}</div><h3>${chName(id)}</h3></div><div class="row"><button class="star ${st.w?'on':''}" data-act="weak" data-k="${id}" title="Mark weak">★</button>${ring(n/4,52,5,`<b style="font-size:.85rem">${n}/4</b>`)}</div></div><div class="tasks">${TL.map((_,i)=>tbtn(id,i,st.t[i])).join('')}</div><div class="row sp mut sm" style="margin-top:10px"><span>${chRange(id)}</span>${clTot(id)?`<span class="chip a" style="padding:2px 9px">⏱ ${fmM(clTot(id))}</span>`:''}</div></article>`}
const xRow=k=>{const[g,i]=k.split('.'),a=S.ex[k]||[0,0,0,0];return`<div class="li" style="flex-direction:column;align-items:stretch;gap:10px"><div><div class="sub" style="--c:${EXC[g]}">${esc(EXTRA[g][0])}</div><b class="sm">${esc(EXTRA[g][1][i])}</b></div><div class="tasks">${TL.map((_,x)=>tbtn(k,x,a[x],'xt')).join('')}</div></div>`};
function pgToday(){
 const a=activeIdx();let i=UI.view;if(i==null||i<0||i>=TOTAL)i=a;UI.view=i;
 const d=dInfo(i),date=dayDate(i),done=isDone(i),st=status(),sk=streak(),pct=doneCount()/TOTAL,w=weekOf(i);
 const sc=diff(S.start,today()),ex=diff(today(),examDate());
 const pf=projFinish(),pl=addD(S.start,TOTAL-1),dl=diff(pl,pf),rem=TOTAL-doneCount(),sm=innerWidth<640,yr=pd(pf).getFullYear()!==new Date().getFullYear()?' '+pd(pf).getFullYear():'';
 const dlt=allDone()?'':dl>0?`<i class="bad">+${dl} day${dl>1?'s':''} later</i>`:dl<0?`<i class="ok">${-dl} day${dl<-1?'s':''} earlier</i>`:'<i>on plan</i>';
 const m3=S.exam?`<div class="hm"><span>🎓</span><b>${ex>=0?ex+'<em>d</em>':'Passed'}</b></div>`:`<div class="hm"><span>📚</span><b>${rem}<em>d</em></b></div>`;
 let h=`<section class="card hero hx rise" style="${ri()}"><div class="hx-top"><span class="eyebrow">${greet()}${S.name?', '+esc(S.name):''}</span><span class="chip ${st.k}">${st.t}</span></div><div class="hx-head"><div style="min-width:0"><h1>Day ${cnt(i+1)}<small>/ ${TOTAL}</small></h1><div class="hx-date"><span>${fDW(date)} · Week ${w.n}${d.rev?' · 🌿 Revision':''}</span>${done?'<span class="hx-ok">✓ Completed</span>':''}</div></div>${ring(pct,sm?66:96,sm?7:9,`<b style="font-size:${sm?.9:1.4}rem">${Math.round(pct*100)}%</b>`,'JOURNEY')}</div><div class="hx-metrics"><div class="hm"><span><i class="flm">🔥</i></span><b>${sk.cur}<em>d</em></b></div><div class="hm"><span>🏁</span><b>${fD(pf)}${yr}</b></div>${m3}</div><div class="hx-nav"><button class="btn g s" data-act="dprev" ${i<=0?'disabled style="opacity:.4"':''}>‹ Prev</button><button class="btn g s" data-act="dnext" ${i>=TOTAL-1?'disabled style="opacity:.4"':''}>Next ›</button>${i!==a?'<button class="btn p s" data-act="djump">Jump to active</button>':''}<button class="btn g s hx-ed" data-act="editDay" title="Edit day">✏️</button></div></section>`;
 if(st.d>0&&sc>=0&&!allDone())h+=`<div class="card rise row sp wrap" style="${ri()}border-color:color-mix(in srgb,var(--bad) 45%,transparent)"><div><b>⚠️ You are ${st.d} day${st.d>1?'s':''} behind schedule</b><div class="mut sm">Re-plan so that today becomes Day ${a+1} and all dates shift forward.</div></div><button class="btn p s" data-act="replan">Re-plan from today</button></div>`;
 if(d.rev||(d.rv&&d.rv.length)){
  const cs=weekChs(i),dd=gd(i),dn=cs.filter(c=>dd.rev[c]).length;
  h+=`<section class="card rise" style="${ri()}"><div class="row sp"><div><h3>🌿 Revision of this week</h3><div class="mut sm">Recall without looking, then check the chapter.</div></div><span class="chip a">${dn}/${cs.length}</span></div><div style="margin:14px 0 4px">${bar(cs.length?dn/cs.length*100:0)}</div><div style="margin-top:14px">${cs.length?cs.map(c=>`<div class="li" data-act="rvd" data-k="${c}" style="cursor:pointer">${chk(dd.rev[c])}<div class="t"><div class="sub" style="--c:${SUBJ[CH[c].s].c}">${esc(SUBJ[CH[c].s].n)}</div>${esc(CH[c].n)}</div><span class="mut sm">${chN(c)}/4</span></div>`).join(''):'<div class="empty">No chapters this week.</div>'}</div></section>`;
 }
  if(!d.rev){
  const cs=dChs(i);h+=`<div class="mss m${cs.length}">${cs.map(missionCard).join('')}</div>`;
 }
 const dd=gd(i);
 const xl=S.xl[today()]||[];
 h+=`<section class="card rise" style="${ri()}"><div class="row sp"><div><h3>🎯 Extra quest</h3><div class="mut sm">Read something extra today? Bangla · English · ICT · Biology</div></div><button class="btn p s" data-act="xq">＋ Add</button></div>${xl.length?`<div style="margin-top:12px">${xl.map(xRow).join('')}</div>`:''}</section>`;
 h+=wrapCard(i);
 const dr=dueRev();
 if(dr.length)h+=`<section class="card rise" style="${ri()}"><div class="row sp"><h3>🔁 Spaced revision due</h3><span class="chip bad">${dr.length}</span></div><div style="margin-top:12px">${dr.slice(0,6).map(x=>`<div class="li"><div class="t"><div class="sub" style="--c:${SUBJ[CH[x.id].s].c}">${esc(SUBJ[CH[x.id].s].n)}</div>${esc(CH[x.id].n)}<div class="mut sm">${x.iv}-day revision${x.late>0?' · '+x.late+'d late':''}</div></div><button class="btn p s" data-act="revdone" data-k="${x.id}" data-i="${x.iv}">Done ✓</button></div>`).join('')}</div></section>`;

 h+=`<div class="g4"><div class="card stat tilt rise" style="${ri()}">${cnt(sk.cur)}<span>🔥 Day streak (best ${sk.best})</span></div><div class="card stat tilt rise" style="${ri()}">${cnt(S.act[today()]||0)}<span>Tasks ticked today</span></div><div class="card stat tilt rise" style="${ri()}">${cnt(stats().chs)}<span>Chapters completed</span></div><div class="card stat tilt rise" style="${ri()}">${cnt(TOTAL-doneCount())}<span>Days remaining</span></div></div>`;
 const open=S.todos.filter(t=>!t.done);
 h+=`<section class="card rise" style="${ri()}"><div class="row sp"><h3>✅ Quick tasks</h3><span class="mut sm">${open.length} pending</span></div><div class="row" style="margin:12px 0"><input class="field" id="tdq" placeholder="Add a task and press Enter" maxlength="120" data-enter="addTodo"><button class="btn p" data-act="addTodo">＋</button></div>${open.slice(0,5).map(t=>todoRow(t)).join('')||'<div class="empty">Nothing pending. 🎉</div>'}</section>`;
 h+=`<section class="card rise" style="${ri()}"><label class="l">📝 Day note / reflection</label><textarea class="field" data-in="dnote" placeholder="What went well? What was hard?">${esc(dd.note)}</textarea></section>`;
 return h}
const todoRow=t=>`<div class="li ${t.done?'done':''}">${`<span data-act="todo" data-k="${t.id}" style="cursor:pointer">${chk(t.done)}</span>`}<span class="t">${esc(t.text)}</span><button class="x" data-act="deltodo" data-k="${t.id}">✕</button></div>`;


function openPlan(){
 const bn=n=>String(n).replace(/\d/g,x=>'০১২৩৪৫৬৭৮৯'[x]),tag=id=>{const s=CH[id].s;return `<span class="t" style="background:${SUBJ[s].c}">${esc(SUBJ[s].n)}</span>`};
 const cell=(d,k)=>{const sl=k?d.b:d.a,ra=(k?d.rb:d.ra)||[],rf=d.rf&&d.rf[k];return sl?{key:'s'+sl[1],html:`${tag(sl[1])} ${esc(CH[sl[1]].n)}`}:rf?{key:'r'+ra.join(),html:`🌿 রিভিশন${ra.length?': '+ra.map(c=>esc(CH[c].n)).join(' + '):''}`}:{key:'',html:'—'}};
 const lastCol=(arr,k)=>{let n=0;arr.forEach((d,i)=>{if((k?d.b:d.a)||(d.rf&&d.rf[k]))n=i+1});return n};
 const cs0=d=>{const o=[];[d.a,d.b].forEach(x=>{if(x&&!o.includes(x[1]))o.push(x[1])});return o};
 let rows='',info={},infoS={};
 STATIC.forEach((d,i)=>cs0(d).forEach(c=>{const e=infoS[c]||(infoS[c]={a:i,n:0});e.n++}));
 for(let i=0;i<TOTAL;i++){const d=dInfo(i),S0=STATIC[i]||{a:null,b:null,ra:[],rb:[],rf:[0,0]};
  if(i%7===0)rows+=`<tr class="w"><td colspan="4">সপ্তাহ ${bn(i/7+1)} · দিন ${bn(i+1)}–${bn(Math.min(i+7,TOTAL))}</td></tr>`;
  cs0(d).forEach(c=>{const e=info[c]||(info[c]={a:i,b:i,n:0});e.b=i;e.n++});
  const cx=[0,1].map(k=>{const n=cell(d,k),o=cell(S0,k);return n.key===o.key?n.html:`<div class="now">✨ এখন: ${n.html}</div><div class="was">আগে ছিল: ${o.html}</div>`});
  rows+=`<tr><td class="n">${bn(i+1)}${isDone(i)?' ✓':''}</td><td class="dt">${fD(dayDate(i))}</td><td>${cx[0]}</td><td>${cx[1]}</td></tr>`}
 const L1=lastCol(ROUTINE,0),L2=lastCol(ROUTINE,1),S1=lastCol(STATIC,0),S2=lastCol(STATIC,1);
 let sm='';['P','C','M'].forEach(L=>{const ks=[...new Set([...Object.keys(info),...Object.keys(infoS)])].filter(c=>CH[c].s[0]===L).sort((p,q)=>((info[p]||infoS[p]).a)-((info[q]||infoS[q]).a)),tot=ks.reduce((t,c)=>t+(info[c]?info[c].n:0),0);
  sm+=`<h3>${{P:'পদার্থবিজ্ঞান',C:'রসায়ন',M:'উচ্চতর গণিত'}[L]} (${bn(tot)} দিন)</h3><table class="s"><tr><th>Chapter</th><th>শুরু</th><th>শেষ</th><th>দিন</th><th>বাঁচল</th></tr>${ks.map(c=>{const e=info[c],sv=(infoS[c]?infoS[c].n:0)-(e?e.n:0);return `<tr><td>${tag(c)} ${esc(CH[c].n)}</td><td>${e?'দিন '+bn(e.a+1):'—'}</td><td>${e?'দিন '+bn(e.b+1):'—'}</td><td><b>${bn(e?e.n:0)}</b></td><td>${sv>0?'<b class="now">−'+bn(sv)+'</b>':'—'}</td></tr>`}).join('')}</table>`});
 const doc=`<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>@page{size:A4;margin:12mm}body{font-family:system-ui,'Noto Sans Bengali','Kalpurush',sans-serif;font-size:13px;color:#111;margin:14px}h1{font-size:22px;margin:0}h3{margin:18px 0 6px}.sub{color:#555;margin:3px 0 10px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:4px 6px;text-align:left}th{background:#eee}.n{width:44px;text-align:center;font-weight:700}.dt{width:56px;color:#555}tr.w td{background:#222;color:#fff;font-weight:700}.t{color:#fff;border-radius:4px;padding:1px 6px;font-size:11px;margin-right:4px;white-space:nowrap}tr{page-break-inside:avoid}.s td:nth-child(n+2){text-align:center;width:72px}.pb{page-break-before:always}.now{font-weight:700;color:#0a7a3d}.was{color:#999;text-decoration:line-through;font-size:11px;margin-top:2px}</style></head><body><h1>${bn(TOTAL)} দিনের পড়ার প্ল্যান</h1><div class="sub">${fDW(S.start)} → ${fDW(dayDate(TOTAL-1))}</div><div class="sub">Task ১ শেষ হবে দিন ${bn(L1)} (মূল প্ল্যানে ${bn(S1)}) · Task ২ শেষ হবে দিন ${bn(L2)} (মূল প্ল্যানে ${bn(S2)}) · মোট ${bn(TOTAL)} দিন (মূল ${bn(STATIC.length)})<br>দুই Task-ই আগে শেষ হলে তবেই মোট দিন কমে।</div><table><tr><th>দিন</th><th>তারিখ</th><th>Task ১</th><th>Task ২</th></tr>${rows}</table><div class="pb"></div><h1>Chapter অনুযায়ী সারাংশ</h1><div class="sub">কোন chapter কোন দিন শুরু, কোন দিন শেষ, কত দিন লাগল আর কত দিন বাঁচল</div>${sm}</body></html>`;
 const o=document.createElement('div');o.style.cssText='position:fixed;inset:0;z-index:99999;background:#fff;display:flex;flex-direction:column';
 o.innerHTML='<div style="display:flex;gap:10px;align-items:center;padding:calc(10px + env(safe-area-inset-top,0px)) 14px 10px;background:#111;color:#fff"><b style="flex:1">📄 Full plan</b><button data-p="1" style="padding:8px 14px;border-radius:10px;border:0;background:#f6c15a;font-weight:700">Save as PDF</button><button data-c="1" style="padding:8px 14px;border-radius:10px;border:0;background:#333;color:#fff">Close</button></div><iframe style="flex:1;border:0;width:100%;background:#fff"></iframe>';
 const fr=o.querySelector('iframe');fr.srcdoc=doc;
 o.querySelector('[data-c]').onclick=()=>o.remove();
 o.querySelector('[data-p]').onclick=()=>{try{fr.contentWindow.focus();fr.contentWindow.print()}catch(e){toast('Print not available here','bad')}};
 document.body.appendChild(o)}
function pgRoadmap(){
 const a=activeIdx(),st=status(),fin=projFinish();
 if(UI.wopen==null)UI.wopen=weekOf(a).n;
 let h=`<section class="card rise" style="${ri()}"><div class="row sp wrap" style="gap:18px"><div><div class="eyebrow">Schedule</div><h3 style="margin:6px 0">${fDW(S.start)} → ${fDW(fin)}</h3><span class="chip ${st.k}">${st.t}</span> <span class="chip">${doneCount()}/${TOTAL} days</span></div><div class="row wrap"><div><label class="l">Start date (all dates follow this)</label><input type="date" class="field" value="${S.start}" data-in="start"></div><button class="btn g" data-act="replan" style="align-self:flex-end">Re-plan from today</button></div></div><div style="margin-top:16px">${bar(doneCount()/TOTAL*100)}</div></section>`;
 h+=`<div class="tl2" style="margin-top:22px">`;
 WEEKS.forEach(w=>{let dn=0,n=w.e-w.s+1;for(let k=w.s;k<=w.e;k++)if(isDone(k))dn++;const cur=weekOf(a).n===w.n,open=UI.wopen===w.n;
  h+=`<div class="card wk rise ${cur?'cur':''} ${open?'open':''}" style="${ri()}padding:0"><div class="wh" data-act="wk" data-i="${w.n}"><div class="wn">${w.n}</div><div style="flex:1;min-width:0"><b>Week ${w.n}</b><div class="mut sm">${fD(dayDate(w.s))} – ${fD(dayDate(w.e))} · ${dn===n?'✓ Completed':dn+'/'+n+' days'}</div><div style="margin-top:8px">${bar(dn/n*100)}</div></div><svg class="chev" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M9 6l6 6-6 6"/></svg></div><div class="dl">`;
  for(let k=w.s;k<=w.e;k++){const d=dInfo(k),dn2=isDone(k);h+=`<div class="dr ${dn2?'done':''} ${k===a&&!allDone()?'act':''} ${d.rev?'rv':''}" data-act="goDay" data-i="${k}"><div class="dn">${dn2?'✓':k+1}</div><div style="flex:1;min-width:0"><div class="row sp"><b class="sm">Day ${k+1}${d.rev?' · Revision':''}</b><span class="mut sm">${fD(dayDate(k))}</span></div>${d.rev?'<div class="mut sm">🌿 Revise this week’s chapters</div>':`<div class="dots">${dChs(k).map(c=>`<span class="sd" style="--c:${SUBJ[CH[c].s].c}">${prDot(c)}${esc(CH[c].n)}</span>`).join('')}</div>`}</div></div>`}
  h+=`</div></div>`});
 return h+'</div>'}

/* ----- analytics ----- */
function heat(){const t=today(),days=[];for(let i=111;i>=0;i--)days.push(addD(t,-i));const pre=pd(days[0]).getDay();let h='';for(let i=0;i<pre;i++)h+='<i style="visibility:hidden"></i>';days.forEach((d,i)=>{const v=S.act[d]||0,l=v<=0?0:v<4?1:v<9?2:v<15?3:4;h+=`<i data-l="${l}" style="--d:${i}" title="${fD(d)} · ${v} tasks"></i>`});return`<div class="heat">${h}</div>`}
function weekBars(){const t=today(),vals=[],labs=[];for(let i=6;i>=0;i--){const d=addD(t,-i);vals.push(S.act[d]||0);labs.push(WD[pd(d).getDay()])}const mx=Math.max(...vals,8),W=320,H=170,bw=W/7;return`<svg class="ch" viewBox="0 0 ${W} ${H}" style="width:100%">${vals.map((v,i)=>{const h=Math.max((H-44)*v/mx,2),x=i*bw+bw*.2;return`<rect class="grow" style="--d:${i}" x="${x}" y="${H-24-h}" width="${bw*.6}" height="${h}" rx="6" fill="${i===6?'var(--a2)':'var(--a1)'}" opacity="${v?1:.25}"/><text x="${x+bw*.3}" y="${H-8}" text-anchor="middle">${labs[i]}</text>${v?`<text x="${x+bw*.3}" y="${H-30-h}" text-anchor="middle">${v}</text>`:''}`}).join('')}</svg>`}
function journey(){const W=340,H=190,L=30,R=10,T0=14,B=26,el=clamp(diff(S.start,today()),0,TOTAL),x=v=>L+(W-L-R)*v/TOTAL,y=v=>T0+(H-T0-B)*(1-v/TOTAL),c=new Array(TOTAL+1).fill(0);for(const i in S.days)if(S.days[i].done)c[clamp(diff(S.start,iso(new Date(S.days[i].done))),0,TOTAL)]++;let run=0;const pts=[];for(let d=0;d<=el;d++){run+=c[d];pts.push([x(d),y(run)])}
 let g='';[0,25,50,75,TOTAL].forEach(v=>g+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="0" y="${y(v)+3}">${v}</text><text x="${x(v)}" y="${H-6}" text-anchor="middle">D${v}</text>`);
 const ln=pts.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' '),last=pts[pts.length-1];
 return`<svg class="ch" viewBox="0 0 ${W} ${H}" style="width:100%"><defs><linearGradient id="ja" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--a1);stop-opacity:.35"/><stop offset="1" style="stop-color:var(--a1);stop-opacity:0"/></linearGradient></defs>${g}<line x1="${x(0)}" y1="${y(0)}" x2="${x(TOTAL)}" y2="${y(TOTAL)}" stroke="var(--mut)" stroke-dasharray="4 5" opacity=".6"/><path d="${ln} L${last[0]},${y(0)} L${x(0)},${y(0)}Z" fill="url(#ja)"/><path class="draw" pathLength="1" d="${ln}" fill="none" stroke="url(#gr)" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${last[0]}" cy="${last[1]}" r="5" fill="var(--a1)"/><circle cx="${last[0]}" cy="${last[1]}" r="10" fill="none" stroke="var(--a1)" opacity=".4"><animate attributeName="r" values="5;14;5" dur="2s" repeatCount="indefinite"/></circle></svg>`}
function radar(){const ks=Object.keys(SUBJ),cx=120,cy=112,R=80,n=ks.length,ang=i=>-Math.PI/2+i*2*Math.PI/n,P=(i,f)=>[cx+Math.cos(ang(i))*R*f,cy+Math.sin(ang(i))*R*f],pv=ks.map(k=>{const ids=CHL[k]||[];return ids.length?ids.reduce((a,i)=>a+chN(i),0)/(ids.length*4):0});let g='';[.25,.5,.75,1].forEach(f=>g+=`<polygon points="${ks.map((_,i)=>P(i,f).join(',')).join(' ')}" fill="none" stroke="var(--line)"/>`);ks.forEach((k,i)=>{const p=P(i,1),q=P(i,1.22);g+=`<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}" stroke="var(--line)"/><text x="${q[0]}" y="${q[1]+3}" text-anchor="middle" style="fill:${SUBJ[k].c};font-weight:700">${SUBJ[k].e.replace('Chemistry','Chem').replace('Physics','Phy').replace('Higher ','')}</text>`});return`<svg class="ch" viewBox="0 0 240 230" style="width:100%;max-width:340px;margin:auto;display:block">${g}<polygon class="rad" points="${pv.map((v,i)=>P(i,Math.max(v,.03)).join(',')).join(' ')}" fill="var(--a1)" fill-opacity=".22" stroke="var(--a1)" stroke-width="2"/>${pv.map((v,i)=>{const p=P(i,Math.max(v,.03));return`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="${SUBJ[ks[i]].c}"/>`}).join('')}</svg>`}
function typeBars(){const ids=Object.keys(CH);return TL.map((l,i)=>{const n=ids.filter(id=>gc(id).t[i]).length,p=Math.round(n/ids.length*100);return`<div style="margin-bottom:12px"><div class="row sp sm"><b>${l}</b><span class="mut">${n}/${ids.length} · ${p}%</span></div>${bar(p)}</div>`}).join('')}
function pgStats(){const s=stats(),done=s.days,rem=TOTAL-done,ex=diff(today(),examDate()),dl=Math.max(1,ex),st=status(),pct=done/TOTAL,el=clamp(diff(S.start,today())+1,1,TOTAL),ids=Object.keys(CH),tt=ids.length*4,td=ids.reduce((a,i)=>a+chN(i),0);
 let h=`<section class="card hero rise" style="${ri()}"><div style="position:relative;z-index:1"><div class="eyebrow">Where you are</div><h1 style="margin:8px 0 10px">Day ${cnt(el)}<small>/ ${TOTAL}</small></h1><div class="row wrap"><span class="chip ${st.k}">${st.t}</span><span class="chip">🔥 ${s.cur} day streak</span><span class="chip">🎓 ${ex>=0?ex+' days to exam':'Exam passed'}</span></div><div class="mut sm" style="margin-top:14px;max-width:420px">${done} of ${TOTAL} days complete · ${rem} to go · ${td}/${tt} core tasks ticked.</div></div>${ring(pct,150,11,`<b style="font-size:2rem">${Math.round(pct*100)}%</b>`,'JOURNEY')}</section>`;
 h+=`<div class="g4" style="margin-top:16px">${[[s.days,'Days completed'],[s.chs,'Chapters finished'],[s.tasks,'Tasks ticked'],[s.best,'Best streak (days)']].map(x=>`<div class="card stat tilt rise" style="${ri()}">${cnt(x[0])}<span>${x[1]}</span></div>`).join('')}</div>`;
 h+=statViz();
 h+=`<section class="card rise" style="margin-top:16px;${ri()}"><div class="row sp"><h3>Consistency · last 16 weeks</h3><span class="mut sm">brighter = more tasks</span></div><div style="margin-top:14px">${heat()}</div></section>`;
 h+=`<div class="g2" style="margin-top:16px"><section class="card rise" style="${ri()}"><h3 style="margin-bottom:10px">Subject balance</h3>${radar()}</section><section class="card rise" style="${ri()}"><h3 style="margin-bottom:10px">Tasks · this week</h3>${weekBars()}<h3 style="margin:18px 0 12px">By task type</h3>${typeBars()}</section></div>`;
 h+=`<section class="card rise" style="margin-top:16px;${ri()}"><div class="row sp wrap"><h3>Your journey</h3><span class="mut sm">dashed = ideal pace · solid = you</span></div><div style="margin-top:12px">${journey()}</div></section>`;
 h+=`<section class="card rise" style="margin-top:16px;${ri()}"><h3>🎯 Pace</h3><div class="g3" style="margin-top:14px"><div><b style="font-size:1.4rem">${rem}</b><div class="mut sm">days of plan left</div></div><div><b style="font-size:1.4rem">${ex>=0?dl:0}</b><div class="mut sm">days until exam</div></div><div><b style="font-size:1.4rem" class="grad">${(rem/dl).toFixed(2)}</b><div class="mut sm">plan-days needed per day</div></div></div></section>`;
 h+=`<div class="eyebrow" style="margin:26px 4px 12px">Subjects</div><div class="g3">${Object.keys(SUBJ).map(k=>{const ids=CHL[k]||[],full=ids.filter(i=>chN(i)===4).length,tasks=ids.reduce((a,i)=>a+chN(i),0),p=ids.length?tasks/(ids.length*4):0;return`<article class="card tilt rise" style="--c:${SUBJ[k].c};${ri()}"><div class="row sp"><div><div class="sub">${esc(SUBJ[k].e)}</div><h3 style="margin-top:4px">${esc(SUBJ[k].n)}</h3></div>${ring(p,58,6,`<b style="font-size:.85rem">${Math.round(p*100)}%</b>`)}</div><div style="margin:14px 0 8px">${bar(p*100,SUBJ[k].c)}</div><div class="row sp sm mut"><span>${full}/${ids.length} chapters</span><span>${tasks}/${ids.length*4} tasks</span></div></article>`}).join('')}</div>`;
 h+=`<div class="eyebrow" style="margin:26px 4px 12px">Extra subjects</div><div class="g3">${Object.keys(EXTRA).map(k=>{const[t,l]=EXTRA[k],d=l.filter((_,i)=>(S.ex[k+'.'+i]||[]).filter(Boolean).length===4).length,p=Math.round(d/l.length*100);return`<article class="card rise" style="--c:${EXC[k]};${ri()}"><div class="sub">${esc(t)}</div><div style="margin:12px 0 8px">${bar(p,EXC[k])}</div><div class="row sp sm mut"><span>${d}/${l.length} done</span><span>${p}%</span></div></article>`}).join('')}</div>`;
 if(S.tests.length){const ts=[...S.tests].sort((a,b)=>a.date.localeCompare(b.date));h+=`<section class="card rise" style="margin-top:16px;${ri()}"><h3 style="margin-bottom:10px">Mock test trend</h3>${lineChart(ts.map(t=>Math.round(t.marks/t.total*1000)/10),ts.map(t=>fD(t.date)))}</section>`}
   h+=priCard()+achSection(stats());return h}

function chapterList(){const q=UI.q.toLowerCase();let h='';
 if(UI.cseg==='core'){Object.keys(SUBJ).forEach(k=>{const ids=(CHL[k]||[]).filter(i=>(!q||(SUBJ[k].n+CH[i].n+SUBJ[k].e).toLowerCase().includes(q))&&fpOk(i));if(!ids.length)return;const all=CHL[k],full=all.filter(i=>chN(i)===4).length,open=UI.open.has(k)||!!q||UI.fp!=='';
  h+=`<div class="card wk ${open?'open':''}" id="sj-${k}" style="padding:0;margin-bottom:12px;--c:${SUBJ[k].c}"><div class="wh" data-act="acc" data-k="${k}"><div class="wn" style="background:${SUBJ[k].c};color:#111;border:0">${k}</div><div style="flex:1"><b>${esc(SUBJ[k].n)}</b><div class="mut sm">${full}/${all.length} chapters complete</div><div style="margin-top:8px">${bar(all.reduce((a,i)=>a+chN(i),0)/(all.length*4)*100,SUBJ[k].c)}</div></div><svg class="chev" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M9 6l6 6-6 6"/></svg></div><div class="dl">${ids.map(i=>{const st=gc(i);return`<div class="li cr ${chN(i)===4?'full':''}" data-ch="${i}" style="flex-direction:column;align-items:stretch;gap:10px;${prOf(i)?`border-left:3px solid ${PRI[prOf(i)][1]}`:''}"><div class="row sp"><div><b class="sm">${chName(i)}</b><div class="mut sm">${chRange(i)}${clTot(i)?' · ⏱ '+fmM(clTot(i)):''}</div><div class="tgs">${tagChips(i)}</div></div><button class="star ${st.w?'on':''}" data-act="weak" data-k="${i}">★</button></div><div class="cbar"><i style="width:${chN(i)*25}%"></i></div><div class="tasks">${TL.map((_,x)=>tbtn(i,x,st.t[x])).join('')}</div></div>`}).join('')}</div></div>`})}
 else{Object.keys(EXTRA).forEach(k=>{const[t,list]=EXTRA[k];const idx=list.map((n,i)=>i).filter(i=>!q||(t+list[i]).toLowerCase().includes(q));if(!idx.length)return;const done=list.filter((_,i)=>(S.ex[k+'.'+i]||[]).filter(Boolean).length===4).length,open=UI.open.has(k)||!!q;
  h+=`<div class="card wk ${open?'open':''}" style="padding:0;margin-bottom:12px"><div class="wh" data-act="acc" data-k="${k}"><div style="flex:1"><b>${esc(t)}</b><div class="mut sm">${done}/${list.length} complete</div><div style="margin-top:8px">${bar(done/list.length*100)}</div></div><svg class="chev" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M9 6l6 6-6 6"/></svg></div><div class="dl">${idx.map(i=>{const a=S.ex[k+'.'+i]||[0,0,0,0];return`<div class="li" style="flex-direction:column;align-items:stretch;gap:10px"><b class="sm">${esc(list[i])}</b><div class="tasks">${TL.map((_,x)=>tbtn(k+'.'+i,x,a[x],'xt')).join('')}</div></div>`}).join('')}</div></div>`})}
 return h||'<div class="empty">Nothing found 🔍</div>'}
function pgChapters(){return chHero(UI.cseg==='core')+`<div class="row wrap rise" style="${ri()}margin-bottom:16px"><div class="seg" style="flex:1;min-width:240px"><button class="${UI.cseg==='core'?'on':''}" data-act="cseg" data-k="core">Core · 84-day plan</button><button class="${UI.cseg==='extra'?'on':''}" data-act="cseg" data-k="extra">Extra · Bangla / English / ICT / Bio</button></div></div>${fpBar()}<input class="field rise" style="${ri()}margin-bottom:16px" id="cq" placeholder="🔍 Search chapters…" value="${esc(UI.q)}" data-in="cq"><div id="clist" class="rise" style="${ri()}">${chapterList()}</div>`}

function lineChart(pts,labs){const W=320,H=170,L=26,R=10,T0=12,B=24;if(!pts.length)return'<div class="empty">No data yet.</div>';const x=i=>pts.length===1?L+(W-L-R)/2:L+i*(W-L-R)/(pts.length-1),y=v=>T0+(H-T0-B)*(1-v/100);let g='';[0,25,50,75,100].forEach(p=>g+=`<line x1="${L}" x2="${W-R}" y1="${y(p)}" y2="${y(p)}" stroke="var(--line)"/><text x="0" y="${y(p)+3}">${p}</text>`);const path=pts.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' '),step=Math.ceil(pts.length/6);return`<svg class="ch" viewBox="0 0 ${W} ${H}" style="width:100%">${g}<path class="draw" pathLength="1" d="${path}" fill="none" stroke="url(#gr)" stroke-width="2.6" stroke-linecap="round"/>${pts.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.6" fill="var(--a1)"/>`).join('')}${labs.map((l,i)=>i%step===0||i===labs.length-1?`<text x="${x(i)}" y="${H-6}" text-anchor="middle">${l}</text>`:'').join('')}</svg>`}
function pgSpace(){const sp=UI.space;let h=wsTabs(sp);
 if(sp==='tasks'){const so=[...S.todos].sort((a,b)=>a.done-b.done);h+=`<section class="card rise" style="${ri()}"><div class="row" style="margin-bottom:14px"><input class="field" id="tdq" placeholder="New task…" maxlength="120" data-enter="addTodo"><button class="btn p" data-act="addTodo">＋</button></div>${so.map(todoRow).join('')||'<div class="empty">No tasks. Add one above ✍️</div>'}${S.todos.some(t=>t.done)?'<button class="btn g s" data-act="clrTodo">Clear completed</button>':''}</section>`}
 if(sp==='notes'){h+=`<div class="row sp rise" style="${ri()}margin-bottom:14px"><input class="field" id="nq" placeholder="🔍 Search notes…" data-in="nq" style="max-width:340px"><button class="btn p" data-act="newNote">＋ New note</button></div><div class="g3" id="nlist">${noteCards('')}</div>`}
 if(sp==='music'){h+=pgMusic()}
 if(sp==='tests'){h+=pgTests()}
 return h}
const noteCards=q=>{q=q.toLowerCase();const l=S.notes.filter(n=>!q||(n.title+n.body).toLowerCase().includes(q)).sort((a,b)=>b.ts-a.ts);return l.map(n=>`<article class="card note tilt rise" style="${ri()}" data-act="openNote" data-k="${n.id}"><b>${esc(n.title||'Untitled')}</b><p>${esc(n.body)||'Empty note'}</p><span class="mut sm" style="margin-top:auto">${fD(iso(new Date(n.ts)))}</span></article>`).join('')||'<div class="empty" style="grid-column:1/-1">No notes yet.</div>'};

const THEMES=[['obsidian','Obsidian','#f6c15a','#ff8a4c','#09090b'],['graphite','Graphite','#e5e7eb','#9ca3af','#0e0f12'],['midnight','Midnight','#60a5fa','#6366f1','#060a1a'],['ink','Ink','#8b9bff','#c084fc','#070a14'],['ocean','Ocean','#38bdf8','#22d3ee','#050b10'],['forest','Forest','#4ade80','#2dd4bf','#060d0a'],['emerald','Emerald','#34d399','#10b981','#04100c'],['violet','Violet','#c084fc','#f472b6','#0a0612'],['rose','Rose','#fda4af','#fb7185','#120709'],['ember','Ember','#ff7a45','#ff3d6e','#0d0706'],['sunset','Sunset','#fb923c','#e879f9','#12080a'],['crimson','Crimson','#f87171','#dc2626','#0f0507'],['paper','Paper','#c2761b','#d9480f','#f5f1e8',1],['snow','Snow','#2563eb','#7c3aed','#f4f6fb',1],['mint','Mint','#059669','#0891b2','#eefaf4',1],['lavender','Lavender','#7c3aed','#db2777','#f6f3ff',1]];
const BGS=[['fireflies','🪲 Fireflies'],['matrix','🟩 Matrix'],['bubbles','🫧 Bubbles'],['stars','✨ Starfield'],['aurora','🌌 Aurora'],['particles','🕸 Network'],['waves','🌊 Waves'],['grid','🔷 Cyber grid'],['none','⛔ Off']];
const sw=(k,on)=>`<label class="sw"><input type="checkbox" data-in="${k}" ${on?'checked':''}><i></i></label>`;
function pgSettingsOld(){const s=S.set;
 return`<div class="g2" style="align-items:start"><div class="stack">
 ${linksCard()}<section class="card rise" style="${ri()}"><h3 style="margin-bottom:14px">📅 Schedule</h3><div class="fg"><label class="l">Start date — Day 1 (everything is calculated from here)</label><input type="date" class="field" value="${S.start}" data-in="start"></div><div class="fg"><label class="l">Exam date</label><input type="date" class="field" value="${examDate()}" data-in="exam"></div><div class="mut sm" style="margin-bottom:12px">Plan finishes on <b>${fDW(addD(S.start,TOTAL-1))}</b>.</div><button class="btn g" data-act="replan">Re-plan from today</button></section>
 <section class="card rise" style="${ri()}"><h3 style="margin-bottom:14px">👤 Profile & goals</h3><div class="fg"><label class="l">Your name</label><input class="field" value="${esc(S.name)}" data-in="name" maxlength="30"></div><button class="btn g" data-act="editWhy">Edit “My Why”</button></section>
 <section class="card rise" style="${ri()}"><h3 style="margin-bottom:6px">☁️ Cloud sync</h3><div class="mut sm" style="margin-bottom:12px">${FB_CONFIG.databaseURL?'All data is saved to Firebase Realtime Database and syncs across your devices.':'Firebase is not connected yet — paste your config into FB_CONFIG at the top of the script. Until then data stays on this device.'}</div><div class="row"><span id="cl2" class="chip a">⚡ Auto-sync is always on — no save button needed</span></div></section></div>
 <div class="stack"><section class="card rise" style="${ri()}"><h3 style="margin-bottom:14px">🎨 Appearance</h3><label class="l">Theme</label><div class="th" style="margin-bottom:18px">${THEMES.map(t=>`<div class="thm ${s.theme===t[0]?'on':''}" data-act="theme" data-k="${t[0]}"><i style="background:linear-gradient(120deg,${t[2]},${t[3]});box-shadow:inset 0 0 0 99px ${t[4]}55"></i>${t[1]}</div>`).join('')}</div><label class="l">Background animation</label><div class="th" style="margin-bottom:16px">${BGS.map(b=>`<div class="thm ${(b[0]==='auto'?s.auto:!s.auto&&s.bg===b[0])?'on':''}" data-act="bg" data-k="${b[0]}">${b[1]}</div>`).join('')}</div><div class="fg"><label class="l">Animation intensity</label><input type="range" min="10" max="100" value="${s.bgI}" data-in="bgI"></div><div class="row sp" style="margin-bottom:14px"><span>Calm mode (turn off all motion)</span>${sw('calm',s.calm)}</div><div class="fg"><label class="l">Text size</label><input type="range" min="14" max="20" value="${s.fs}" data-in="fs"></div><label class="l">Card style</label><div class="seg" style="margin-bottom:14px">${[['glass','Glass'],['solid','Solid'],['outline','Outline'],['neon','Neon']].map(x=>`<button class="${(s.cs||'glass')===x[0]?'on':''}" data-act="cs" data-k="${x[0]}">${x[1]}</button>`).join('')}</div><div class="fg"><label class="l">Roundness</label><input type="range" min="6" max="32" value="${s.rd==null?20:s.rd}" data-in="rd"></div><label class="l">Custom colours</label><div class="row wrap" style="gap:14px"><label class="cpk">Accent 1<input type="color" value="${s.c1}" data-in="c1"></label><label class="cpk">Accent 2<input type="color" value="${s.c2}" data-in="c2"></label><label class="cpk">Background<input type="color" value="${s.cbg}" data-in="cbg"></label></div></section>
 <section class="card rise" style="${ri()}"><h3 style="margin-bottom:6px">🖼 App icon</h3><div class="mut sm" style="margin-bottom:14px">Upload your own logo. It changes the in-app logo and browser icon. For the phone home-screen icon, install (or re-install) the app after uploading.</div><div class="row wrap"><div style="width:64px;height:64px;border-radius:16px;overflow:hidden" class="logo">${logoSVG()}</div><label class="btn g" style="cursor:pointer">Upload image<input type="file" accept="image/*" data-in="icon" style="display:none"></label>${s.icon?'<button class="btn d s" data-act="iconReset">Reset</button>':''}</div></section>
 <section class="card rise" style="${ri()}"><h3 style="margin-bottom:14px">💾 Data</h3><div class="row wrap"><button class="btn g" data-act="export">Export backup</button><label class="btn g" style="cursor:pointer">Import backup<input type="file" accept=".json,application/json" data-in="import" style="display:none"></label><button class="btn g" data-act="freshStart">🚀 Fresh start (go live)</button><button class="btn d" data-act="resetAll">Reset everything</button></div><div class="mut sm" style="margin-top:12px">Data is saved on this device and, if Firebase is connected, in the cloud. Export a backup now and then.</div></section></div></div>`}

function pgWhy(){const L=(S.why||'').split(/\n+/).map(x=>x.trim()).filter(Boolean),dn=S.ms.filter(m=>m.done).length;
 return`<section class="card vision rise" style="${ri()}"><div class="row sp wrap"><div><div class="eyebrow">🧭 My Why</div><h3 style="margin-top:6px">The reasons that keep you going</h3></div><div class="row"><button class="btn g s" data-act="replay">▶ Play intro</button><button class="btn p s" data-act="editWhy">${L.length?'Edit':'Write my Why'}</button></div></div><div style="margin-top:18px">${L.length?L.map((l,i)=>`<div class="wl"><b>${i+1}</b><p>${esc(l)}</p></div>`).join(''):'<div class="empty">Write your goals and reasons — one per line. They will greet you every time you open the app.</div>'}</div></section>
 <section class="card rise" style="margin-top:16px;${ri()}"><div class="row sp"><h3>🏁 Milestones</h3><span class="chip a">${dn}/${S.ms.length}</span></div><div style="margin:12px 0">${bar(S.ms.length?dn/S.ms.length*100:0)}</div><div class="row" style="margin-bottom:12px"><input class="field" id="msq" placeholder="e.g. Finish all Physics by day 60" maxlength="100" data-enter="addMs"><button class="btn p" data-act="addMs">＋</button></div>${S.ms.map(m=>`<div class="li ${m.done?'done':''}"><span data-act="ms" data-k="${m.id}" style="cursor:pointer">${chk(m.done)}</span><span class="t">${esc(m.text)}</span><button class="x" data-act="delMs" data-k="${m.id}">✕</button></div>`).join('')||'<div class="empty">Add milestones that make your goal real.</div>'}</section>`}
function closeSplash0(now){const e=$('#ws');if(!e)return;if(now){e.remove();return}e.classList.add('out');setTimeout(()=>e.remove(),500)}
function splash0(force){const L=(S.why||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).slice(0,12);if(!L.length)return;if(!force&&sessionStorage.getItem('mm_ws'))return;try{sessionStorage.setItem('mm_ws','1')}catch(e){}closeSplash(true);let t=.8;
 const rows=L.map((l,n)=>{const w=l.split(/\s+/).map(x=>{const s=`<span class="ws-w" style="animation-delay:${t.toFixed(2)}s">${esc(x)}</span>`;t+=.085;return s}).join(' ');t+=.55;return`<p class="ws-l${L.length>1?' n':''}"${L.length>1?` data-n="${n+1}"`:''}>${w}</p>`}).join('');
 const el=document.createElement('div');el.id='ws';el.innerHTML=`<div class="ws-o"><i></i><i></i></div><button class="ws-skip" data-act="splashGo">Skip ›</button><div class="ws-in"><div class="ws-e">🧭 My Why</div><h2 class="ws-h">${S.name?esc(S.name)+', remember why you started.':'Remember why you started.'}</h2><div>${rows}</div><button class="btn p big ws-b" data-act="splashGo" style="animation-delay:${(t+.3).toFixed(2)}s">Begin today →</button></div>`;document.body.appendChild(el)}
