document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const b=el.closest('.btn,.task,.seg button,.nv,#tabs button,.lkt');if(b&&!S.set.calm){const r=b.getBoundingClientRect(),s=document.createElement('span');s.className='rip';const z=Math.max(r.width,r.height);s.style.cssText=`width:${z}px;height:${z}px;left:${e.clientX-r.left-z/2}px;top:${e.clientY-r.top-z/2}px`;b.appendChild(s);setTimeout(()=>s.remove(),600)}const f=ACT[el.dataset.act];f&&f(el,e)});
