  c1:e=>{S.set.c1=e.value;S.set.theme='custom';save();applyTheme()},c2:e=>{S.set.c2=e.value;S.set.theme='custom';save();applyTheme()},cbg:e=>{S.set.cbg=e.value;S.set.theme='custom';save();applyTheme()},rd:e=>{S.set.rd=+e.value;save();applyStyle()},
