 icon:e=>{const f=e.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d'),s=Math.min(im.width,im.height);x.drawImage(im,(im.width-s)/2,(im.height-s)/2,s,s,0,0,512,512);S.set.icon=c.toDataURL('image/png');save();applyIcon();render(false);toast('Icon updated. Re-install the app to change the home-screen icon.','ok')};im.src=r.result};r.readAsDataURL(f)},
