const h2r=h=>{h=(h||'').trim();if(h[0]!=='#')return[255,200,100];if(h.length===4)h='#'+[...h.slice(1)].map(c=>c+c).join('');const n=parseInt(h.slice(1),16);return[n>>16&255,n>>8&255,n&255]};
const cols=()=>{const cs=getComputedStyle(document.documentElement);return[h2r(cs.getPropertyValue('--a1')),h2r(cs.getPropertyValue('--a2'))]};
const rgba=(c,a)=>`rgba(${c[0]},${c[1]},${c[2]},${a})`;
function bgSize(){BG.dpr=Math.min(devicePixelRatio||1,document.body.classList.contains('lite')?1:1.5);BG.w=innerWidth;BG.h=innerHeight;BG.c.width=BG.w*BG.dpr;BG.c.height=BG.h*BG.dpr;BG.x.setTransform(BG.dpr,0,0,BG.dpr,0,0);bgSeed()}
function bgSeed(){const k=S.set.bgI/100,m=S.set.bg,r=Math.random;BG.P=[];seedX(k,m,r);if(m==='stars')for(let i=0;i<Math.round(160+600*k);i++)BG.P.push({x:r()*BG.w,y:r()*BG.h,z:r()*r(),tw:.5+r()*2,ph:r()*6});if(m==='aurora')for(let i=0;i<7;i++)BG.P.push({x:r()*BG.w,y:r()*BG.h,r:Math.max(BG.w,BG.h)*(.28+r()*.22),vx:(r()-.5)*40,vy:(r()-.5)*28,c:i%2});if(m==='particles')for(let i=0;i<Math.round(36+90*k*Math.min(1,BG.w/900+.3));i++)BG.P.push({x:r()*BG.w,y:r()*BG.h,vx:(r()-.5)*28,vy:(r()-.5)*28,s:1+r()*1.6})}
function bgDraw(dt){const{x,w,h}=BG,k=S.set.bgI/100,[a1,a2]=cols(),light=!!(THEMES.find(x=>x[0]===S.set.theme)||[])[5];x.clearRect(0,0,w,h);BG.t+=dt;const t=BG.t;
 if(S.set.bg==='stars'){const base=light?a1:[255,255,255];BG.P.forEach(p=>{p.y-=p.z*8*dt;p.x-=p.z*3*dt;if(p.y<-5)p.y=h+5;if(p.x<-5)p.x=w+5;const px=p.x+(BG.mx-.5)*p.z*30,py=p.y+(BG.my-.5)*p.z*30,a=(.25+.6*(.5+.5*Math.sin(t*p.tw+p.ph)))*(.4+.6*k)*(light?.7:1);x.fillStyle=rgba(p.z>.8?a1:base,a);x.beginPath();x.arc(px,py,p.z*1.5+.3,0,6.283);x.fill()});BG.nextSh-=dt;if(BG.nextSh<0&&!BG.sh){BG.nextSh=4+Math.random()*7;BG.sh={x:w*(.3+Math.random()*.7),y:Math.random()*h*.4,l:0}}if(BG.sh){const s=BG.sh;s.l+=dt*1.6;s.x-=dt*520;s.y+=dt*260;const g=x.createLinearGradient(s.x,s.y,s.x+120,s.y-60);g.addColorStop(0,rgba(a1,.9*(1-s.l)));g.addColorStop(1,rgba(a1,0));x.strokeStyle=g;x.lineWidth=1.6;x.beginPath();x.moveTo(s.x,s.y);x.lineTo(s.x+120,s.y-60);x.stroke();if(s.l>=1)BG.sh=null}}
 else if(S.set.bg==='aurora'){x.globalCompositeOperation=light?'source-over':'lighter';BG.P.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1;const rr=p.r*(1+.12*Math.sin(t*.4+p.c)),g=x.createRadialGradient(p.x,p.y,0,p.x,p.y,rr);g.addColorStop(0,rgba(p.c?a2:a1,(light?.22:.2)*k));g.addColorStop(1,rgba(p.c?a2:a1,0));x.fillStyle=g;x.fillRect(0,0,w,h)});x.globalCompositeOperation='source-over'}
 else if(S.set.bg==='particles'){const P=BG.P,d2=130*130;P.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1;const dx=p.x-BG.mx*w,dy=p.y-BG.my*h,dd=dx*dx+dy*dy;if(dd<14000){p.x+=dx*dt*1.4;p.y+=dy*dt*1.4}});for(let i=0;i<P.length;i++){const p=P[i];x.fillStyle=rgba(a1,.7*k+.15);x.beginPath();x.arc(p.x,p.y,p.s,0,6.283);x.fill();for(let j=i+1;j<P.length;j++){const q=P[j],dx=p.x-q.x,dy=p.y-q.y,d=dx*dx+dy*dy;if(d<d2){x.strokeStyle=rgba(a1,(1-d/d2)*.28*k);x.lineWidth=.8;x.beginPath();x.moveTo(p.x,p.y);x.lineTo(q.x,q.y);x.stroke()}}}}
 else if(S.set.bg==='waves'){for(let i=0;i<4;i++){const by=h*(.62+.08*i),amp=18+i*9,f=.004-i*.0005,sp=t*(.5+i*.2);const g=x.createLinearGradient(0,by-amp,0,h);g.addColorStop(0,rgba(i%2?a2:a1,(.1+.04*i)*k*(light?1.3:1)));g.addColorStop(1,rgba(i%2?a2:a1,0));x.fillStyle=g;x.beginPath();x.moveTo(0,h);for(let X=0;X<=w;X+=10)x.lineTo(X,by+Math.sin(X*f+sp)*amp+Math.sin(X*f*2.3-sp*1.3)*amp*.4);x.lineTo(w,h);x.closePath();x.fill()}}
 else if(drawX(t,dt,a1,a2,k,light)){}
 else if(S.set.bg==='grid'){const hz=h*.5,N=14,vx=w/2+(BG.mx-.5)*60;x.lineWidth=1;for(let i=-16;i<=16;i++){x.strokeStyle=rgba(a1,.22*k);x.beginPath();x.moveTo(vx+i*6,hz);x.lineTo(vx+i*(w/9),h);x.stroke()}for(let i=0;i<N;i++){const z=((i+t*.6)%N)/N,y=hz+(h-hz)*z*z;x.strokeStyle=rgba(a2,(.05+.4*z)*k);x.beginPath();x.moveTo(0,y);x.lineTo(w,y);x.stroke()}const g=x.createLinearGradient(0,hz-60,0,hz+40);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(1,rgba(a1,.07*k));x.fillStyle=g;x.fillRect(0,hz-60,w,100)}}
function bgLoop(ts){BG.raf=requestAnimationFrame(bgLoop);const el=ts-BG.last;if(BG.slow&&el<30)return;BG.last=ts;if(el>0&&el<200){BG.fa=(BG.fa||16)*.95+el*.05;if(!BG.slow&&(S.set.perf||'auto')!=='full'&&BG.fa>26&&(BG.fc=(BG.fc||0)+1)>150){BG.slow=true;applyPerf();bgSize();bgSeed()}}bgDraw(Math.min(.05,el/1000||.016))}
function bgStart(){cancelAnimationFrame(BG.raf);BG.raf=0;if(S.set.bg==='none'||S.set.calm||document.hidden||nbg()){BG.x.clearRect(0,0,BG.w,BG.h);return}BG.last=performance.now();BG.raf=requestAnimationFrame(bgLoop)}
addEventListener('resize',()=>{bgSize();bgStart()});
addEventListener('pointermove',e=>{BG.mx=e.clientX/innerWidth;BG.my=e.clientY/innerHeight},{passive:true});
document.addEventListener('visibilitychange',()=>{bgStart()});

/* ============ confetti ============ */
const FX={c:$('#fx'),x:$('#fx').getContext('2d'),P:[],raf:0};
function fxSize(){FX.c.width=innerWidth;FX.c.height=innerHeight}fxSize();addEventListener('resize',fxSize);
function burst(x,y,n=90,pl){if(S.set.calm)return;const[a1,a2]=cols(),pal=pl||[rgba(a1,1),rgba(a2,1),'#5ee6a8','#ffffff','#ffd166'];for(let i=0;i<n;i++){const a=Math.random()*6.283,s=4+Math.random()*9;FX.P.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-5,g:.28,l:1,d:.008+Math.random()*.012,r:Math.random()*6,vr:(Math.random()-.5)*.4,w:5+Math.random()*7,h:3+Math.random()*5,c:pal[i%pal.length]})}if(!FX.raf)FX.raf=requestAnimationFrame(fxLoop)}
function fxLoop(){const{x,c}=FX;x.clearRect(0,0,c.width,c.height);FX.P=FX.P.filter(p=>p.l>0&&p.y<c.height+40);FX.P.forEach(p=>{p.vy+=p.g;p.vx*=.992;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;p.l-=p.d;x.save();x.globalAlpha=Math.max(0,p.l);x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.w/2,-p.h/2,p.w,p.h);x.restore()});FX.raf=FX.P.length?requestAnimationFrame(fxLoop):0;if(!FX.P.length)x.clearRect(0,0,c.width,c.height)}

