/* fresh start: wipe everything (device + Firebase + files) */
const clrDB=(name,store)=>new Promise(ok=>{try{const r=indexedDB.open(name,1);r.onupgradeneeded=()=>{try{r.result.createObjectStore(store)}catch(e){}};r.onerror=()=>ok();r.onblocked=()=>ok();r.onsuccess=()=>{try{const db=r.result;if(!db.objectStoreNames.contains(store)){db.close();return ok()}const tx=db.transaction(store,'readwrite');tx.objectStore(store).clear();tx.oncomplete=()=>{db.close();ok()};tx.onerror=tx.onabort=()=>{db.close();ok()}}catch(e){ok()}}}catch(e){ok()}});
ACT.freshStart=()=>modal(`<h3 style="margin-bottom:10px">🚀 Fresh start (go live)</h3><div class="mut sm" style="margin-bottom:14px;line-height:1.6">This erases <b>everything</b> — progress, tests, tasks, notes, My Why, files, music, YouTube folders, class time and badges — on this device <b>and in Firebase</b>. Only your name and look (theme) stay. It cannot be undone.</div><div class="row wrap"><button class="btn d" id="fsGo" data-act="freshGo">Yes, erase everything</button><button class="btn g" data-act="close">Cancel</button></div>`);
ACT.freshGo=async()=>{const b=$('#fsGo');if(b){b.disabled=true;b.textContent='Erasing…'}
 try{try{AU.pause()}catch(e){}try{ytOff()}catch(e){}
  const N=DEF();N.name=S.name||'';N.set=Object.assign({},S.set,{links:DEF().set.links});N.onb=1;N.start=today();N.u=Date.now();
  await Promise.all([clrDB('mm_vid','v'),clrDB('mm_mus','m')]);
  try{localStorage.removeItem('mm_mus');localStorage.removeItem('mm_mus2');sessionStorage.removeItem('mm_ws')}catch(e){}
  try{MZ.list=[];MZ.idx=-1;AU.removeAttribute('src');AU.load();AQ.length=0}catch(e){}
  Object.keys(S).forEach(k=>delete S[k]);Object.assign(S,N);
  try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}
  if(CL.on&&CL.ref){try{CL.ref.off()}catch(e){}await Promise.race([CL.ref.set({u:S.u,data:JSON.stringify(S)}),new Promise(r=>setTimeout(r,6000))]).catch(()=>{})}
  toast('🚀 Fresh start — everything cleared','ok');
 }catch(e){toast('Something went wrong, reloading…','bad')}
 setTimeout(()=>location.reload(),400)};

