function xRowB(k,i,c,tag){const a=S.ex[k+'.'+i]||[0,0,0,0];return`<div class="xr ${exFull(k,i)?'full':''}" style="--rc:${c||'var(--a1)'}">${tag?`<div class="xr-tag">${esc(tag)}</div>`:''}<div class="xr-n"><span class="bkn">${bnum(i+1)}</span><b>${esc(EXTRA[k][1][i])}</b></div><div class="tasks">${TL.map((_,x)=>tbtn(k+'.'+i,x,a[x],'xt')).join('')}</div></div>`}
function bioBlocks(q,toc){q=(q||'').toLowerCase();const rw=(k,i,c,t)=>toc?tocEx(k,i,i+1):xRowB(k,i,c,t);
 if(q){let h='';BIOB.forEach(b=>b.p.forEach(([k,a])=>a.forEach(n=>{const i=n-1;if((b.t+' '+EXTRA[k][1][i]+' '+PAPB[k]+' bio biology জীববিজ্ঞান').toLowerCase().includes(q))h+=rw(k,i,b.c,b.t+' · '+PAPB[k])})));return h||'<div class="empty">Nothing found 🔍</div>'}
 const cur=BIOB.findIndex(b=>!bioDone(b)),op=UI.xbo||(UI.xbo=new Set());let h='',rest=0;
 BIOB.forEach((b,bi)=>{if(cur>=0&&bi>cur){rest++;return}
  const it=bioItems(b),d=it.filter(([k,i])=>exFull(k,i)).length,done=d===it.length;
  h+=`<section class="xb ${done?'done':''} ${toc?'tc':''}" style="--bc:${b.c}"><div class="xb-h" ${done?`data-act="xbTog" data-k="${b.id}"`:''}><span class="xb-star">${b.t}</span><div class="xb-t"><b>${esc(b.s)}</b><span class="mut sm">${bnum(d)}/${bnum(it.length)} chapter${done?' · ✓ সম্পন্ন':''}</span></div><span class="chip ${done?'ok':'a'}">${done?'✓':Math.round(d/it.length*100)+'%'}</span></div>`;
  if(!done||op.has(b.id)){h+='<div class="xb-pap">';b.p.forEach(([k,a])=>{h+=`<div class="xb-pl">${PAPB[k]}</div>`+a.map(n=>rw(k,n-1,b.c)).join('')});h+='</div>'}
  h+='</section>'});
 if(cur<0)h+='<div class="empty">🎉 সব Bio chapter শেষ!</div>';
 else if(rest)h+=`<div class="xb-lock">🔒 আরও ${bnum(rest)}টি ব্লক বাকি — এই ব্লক শেষ হলেই পরেরটা খুলবে</div>`;
 return h}

